def get_coefficients(n, k):
    # a_{k,i} = sum_{j=1}^n C(k, i, j) * a_{0,j}
    # Initially, a_{0,j} = j, but we want coefficients.
    # Let's use a symbolic approach or just represent each a_{k,i} as a list of coefficients.
    # Each element in the list is a list of coefficients for a_{0,1}, a_{0,2}, ..., a_{0,n}

    # Initial state: a_{0,j} = [0, 0, ..., 1, ..., 0] (1 at index j-1)
    coeffs = [[0] * n for _ in range(n)]
    for i in range(n):
        coeffs[i][i] = 1

    for _ in range(k):
        new_coeffs = []
        for i in range(len(coeffs) - 1):
            new_coeffs.append(coeffs[i])
            new_coeffs.append([coeffs[i][j] + coeffs[i+1][j] for j in range(n)])
        new_coeffs.append(coeffs[-1])
        coeffs = new_coeffs
    return coeffs

n = 3
k = 2
coeffs = get_coefficients(n, k)
for i, c in enumerate(coeffs):
    print(f"a_{k,{i+1}} coefficients: {c}")

import numpy as np

def transform(arr):
    new_arr = []
    for i in range(len(arr) - 1):
        new_arr.append(arr[i])
        new_arr.append(arr[i] + arr[i+1])
    new_arr.append(arr[-1])
    return new_arr

def get_poly(arr):
    return np.poly1d(arr[::-1])

n = 3
arr = list(range(1, n + 1))
polys = []
polys.append(get_poly(arr))
for k in range(1, 3):
    arr = transform(arr)
    polys.append(get_poly(arr))

for k in range(1, 3):
    print(f"Q_{k}: {polys[k]}")
    print(f"Q_{k-1}(x^2): {polys[k-1](np.sqrt(np.array([0, 1, 2, 3, 4, 5, 6])))}") # This is not good
